function task_product_work_area_refresh(frm, show_alert) {
    const is_product_task = task_product_work_area_is_product_task(frm);
    if (!is_product_task) {
        if (frm.fields_dict.custom_task_product_summary) {
            frm.fields_dict.custom_task_product_summary.$wrapper.empty();
        }
        return;
    }
    if (!frm.doc.dispatch_case) {
        task_product_work_area_empty(frm, "No Dispatch Case linked yet.", "warning");
        return;
    }
    frappe.call({
        method: "frappe.client.get",
        args: { doctype: "Dispatch Case", name: frm.doc.dispatch_case },
        callback: function(r) {
            const doc = r.message;
            if (!doc) {
                task_product_work_area_empty(frm, "Linked Dispatch Case was not found.", "danger");
                return;
            }
            let rows = doc.case_items || [];
            if (frm.doc.task_kind === "Returns restocking") {
                rows = rows.filter(function(r) { return flt(r.returned_qty || 0) > 0; });
            }
            if (!rows.length) {
                task_product_work_area_empty(frm, "No product rows yet.", "warning");
                return;
            }
            const is_returns_task = (frm.doc.task_kind === "Returns processing / verification");
            const checkbox_label = is_returns_task ? "Returned?" : "Packed?";
            const col1_label = is_returns_task ? "Dispatched" : "Required";
            const col2_label = is_returns_task ? "Returned" : "Scanned";
            const col3_label = is_returns_task ? "Used" : "Missing";

            let html = `<div class="small text-muted" style="margin-bottom:8px">Source: <b>${frappe.utils.escape_html(doc.name)}</b> | Customer: <b>${frappe.utils.escape_html(doc.customer || "")}</b></div>`;
            html += `<div style="overflow-x:auto"><table class="table table-bordered table-condensed"><thead><tr>
                <th style="width:70px">${checkbox_label}</th><th>Name</th><th>${col1_label}</th><th>${col2_label}</th><th>${col3_label}</th><th>Batch/LOT</th><th>Expiry</th><th>Status</th><th>Warning / Problem</th>
            </tr></thead><tbody>`;
            rows.forEach(function(row, idx) {
                const required = flt(row.dispatched_qty || 0);
                const scanned = flt(row.custom_scanned_qty || 0);
                const remaining = row.custom_remaining_qty !== undefined && row.custom_remaining_qty !== null ? flt(row.custom_remaining_qty) : Math.max(required - scanned, 0);
                const warn = row.custom_fefo_warning || row.custom_problem_reason || "";
                const status = row.custom_packing_status || "Pending";
                const is_packed = is_returns_task ? false : (status === "Complete" || status === "Over Scanned");
                html += `<tr>
                    <td class="text-center">
                        <input type="checkbox" class="pack-checkbox" data-idx="${idx}" ${is_packed ? 'checked' : ''} 
                               style="width:22px;height:22px;min-width:22px;min-height:22px;cursor:pointer;aspect-ratio:1/1"
                               onchange="task_product_work_area_toggle_packed(this)">
                    </td>
                    <td>${frappe.utils.escape_html(row.item_name || row.item_code || "")}</td>
                    <td class="text-right">${required}</td>
                    <td class="text-right">${scanned}</td>
                    <td class="text-right">${remaining}</td>
                    <td>${frappe.utils.escape_html(row.batch_no || "")}</td>
                    <td>${frappe.utils.escape_html(row.expiry_date || row.custom_expiry_date || "")}</td>
                    <td><span class="indicator ${is_packed ? 'green' : 'orange'}">${frappe.utils.escape_html(status)}</span></td>
                    <td>${frappe.utils.escape_html(warn)}</td>
                </tr>`;
            });
            html += `</tbody></table></div>`;
            html += `<div class="small text-muted" style="margin-top:8px"><i>Tip: Check boxes then Save to update packing status.</i></div>`;
            if (frm.fields_dict.custom_task_product_summary) {
                frm.fields_dict.custom_task_product_summary.$wrapper.html(html);
            }
        }
    });
}

function task_product_work_area_toggle_packed(checkbox) {
    if (!cur_frm) return;
    // Count checked vs total to update progress and force a real field change
    var wrapper = cur_frm.fields_dict.custom_task_product_summary;
    if (wrapper) {
        var boxes = wrapper.$wrapper.find("input.pack-checkbox");
        var total = boxes.length;
        var checked = boxes.filter(":checked").length;
        var pct = total > 0 ? Math.round((checked / total) * 100) : 0;
        cur_frm.set_value("progress", pct);
    } else {
        cur_frm.dirty();
    }
}

function task_product_work_area_is_product_task(frm) {
    const kinds = [
        "Pack / prepare items", "Dispatch picking / hand-off", "Delivery", "Return Call", "Pickup Returns",
        "Return drop-off at warehouse", "Returns processing / verification", "Returns restocking",
        "Invoice preparation / create invoice", "Discount Approval"
    ];
    return !!frm.doc.dispatch_case || kinds.includes(frm.doc.task_kind);
}

function task_product_work_area_empty(frm, message, indicator) {
    if (frm.fields_dict.custom_task_product_summary) {
        frm.fields_dict.custom_task_product_summary.$wrapper.html(
            `<div class="alert alert-${indicator || "warning"}">${frappe.utils.escape_html(message)}</div>`
        );
    }
}

frappe.ui.form.on("Task", {
    refresh(frm) {
        // Scroll to top when task opens
        setTimeout(function() {
            window.scrollTo(0, 0);
            $(".main-section").scrollTop(0);
            $(".layout-main-section-wrapper").scrollTop(0);
            $(document).scrollTop(0);
            if (frm.$wrapper && frm.$wrapper.length) {
                frm.$wrapper[0].scrollIntoView(true);
            }
        }, 100);
        // Show pickup photo on Pack, Delivery, Pickup Returns; hide on Order entry
        const showPhotoKinds = ["Pack / prepare items", "Delivery"];
        // Delivery: read-only (just viewing the photo)
        if (frm.doc.task_kind === "Delivery") {
            frm.set_df_property('warehouse_pickup_photo', 'read_only', 1);
        }
        if (showPhotoKinds.includes(frm.doc.task_kind)) {
            frm.set_df_property('warehouse_pickup_photo', 'hidden', 0);
            frm.set_df_property('warehouse_dropoff_photo', 'hidden', 1);
            // Pack tasks: hide default attach control, use only Add Photos button
            if (frm.doc.task_kind === "Pack / prepare items") {
                var photoCtrl = frm.fields_dict.warehouse_pickup_photo;
                if (photoCtrl && photoCtrl.$wrapper) {
                    photoCtrl.$wrapper.find('.control-input').hide();
                }
            }
            // Render image gallery
            task_render_photo_preview(frm);
            // Add Photo button rendered inline for Pack tasks
            if (frm.doc.task_kind === "Pack / prepare items" && !frm.is_new()) {
                task_render_add_photo_btn(frm);
            }
        } else if (frm.doc.task_kind === "Pickup Returns" && !frm.is_new()) {
            frm.set_df_property('warehouse_dropoff_photo', 'hidden', 0);
            frm.set_df_property('warehouse_pickup_photo', 'hidden', 1);
            // Hide default attach control, use only Add Photos button
            var dropCtrl = frm.fields_dict.warehouse_dropoff_photo;
            if (dropCtrl && dropCtrl.$wrapper) {
                dropCtrl.$wrapper.find('.control-input').hide();
            }
            task_render_dropoff_gallery(frm);
            task_render_dropoff_add_photo_btn(frm);
        } else if (frm.doc.task_kind === "Order entry") {
            frm.set_df_property('warehouse_pickup_photo', 'hidden', 1);
            frm.set_df_property('warehouse_dropoff_photo', 'hidden', 1);
        }
        // Prevent auto-save after photo attach on Pickup Returns and Pack tasks
        (function() {
            var fields_to_patch = [];
            if (frm.doc.task_kind === "Pickup Returns") fields_to_patch.push("warehouse_dropoff_photo");
            if (frm.doc.task_kind === "Pack / prepare items") fields_to_patch.push("warehouse_pickup_photo");
            fields_to_patch.forEach(function(fieldname) {
                var ctrl = frm.fields_dict[fieldname];
                if (ctrl && !ctrl._no_auto_save_patched) {
                    ctrl._no_auto_save_patched = true;
                    ctrl.on_upload_complete = function(file_doc) {
                        this.parse_validate_and_set_in_model(file_doc.file_url);
                        if (this.frm) {
                            this.frm.attachments.new_attachment(file_doc);
                            this.frm.dirty();
                        }
                    };
                }
            });
        })();
        task_product_work_area_refresh(frm);
        const is_product_task = task_product_work_area_is_product_task(frm);
        if (!frm.is_new() && is_product_task) {
            frm.add_custom_button(__("Refresh Packing Status"), function() {
                task_product_work_area_refresh(frm, true);
            }, __("Packing"));
        }
    },
    dispatch_case(frm) {
        task_product_work_area_refresh(frm, true);
    },
    task_kind(frm) {
        task_product_work_area_refresh(frm, true);
    },
    before_save(frm) {
        if (!frm.doc.dispatch_case) return;
        if (frm.doc.task_kind !== "Pack / prepare items" && frm.doc.task_kind !== "Returns processing / verification") return;

        const wrapper = frm.fields_dict.custom_task_product_summary;
        if (!wrapper) return;
        const checkboxes = wrapper.$wrapper.find('input.pack-checkbox');
        if (!checkboxes.length) return;

        const packed_indices = [];
        checkboxes.each(function() {
            if (this.checked) {
                packed_indices.push(parseInt($(this).data('idx')));
            }
        });

        frappe.call({
            method: "task_mark_items_packed_batch",
            args: {
                case_name: frm.doc.dispatch_case,
                packed_indices: JSON.stringify(packed_indices),
                task_kind: frm.doc.task_kind
            },
            async: false,
            freeze: true,
            freeze_message: __("Updating packing status...")
        });
    },
    after_save(frm) {
        // Prevent auto-save after photo attach on Pickup Returns and Pack tasks
        (function() {
            var fields_to_patch = [];
            if (frm.doc.task_kind === "Pickup Returns") fields_to_patch.push("warehouse_dropoff_photo");
            if (frm.doc.task_kind === "Pack / prepare items") fields_to_patch.push("warehouse_pickup_photo");
            fields_to_patch.forEach(function(fieldname) {
                var ctrl = frm.fields_dict[fieldname];
                if (ctrl && !ctrl._no_auto_save_patched) {
                    ctrl._no_auto_save_patched = true;
                    ctrl.on_upload_complete = function(file_doc) {
                        this.parse_validate_and_set_in_model(file_doc.file_url);
                        if (this.frm) {
                            this.frm.attachments.new_attachment(file_doc);
                            this.frm.dirty();
                        }
                    };
                }
            });
        })();
        task_product_work_area_refresh(frm);
    }
});

function task_render_photo_preview(frm) {
